import fs from 'fs';
const R = (f, pairs) => {
  let s = fs.readFileSync(f, 'utf8');
  const nl = s.includes('\r\n') ? '\r\n' : '\n';
  for (const [a, b] of pairs) {
    const n = typeof a === 'string' ? s.split(a).length - 1 : (s.match(new RegExp(a.source, a.flags + 'g')) || []).length;
    if (n !== 1) throw new Error(f + ' khớp ' + n + ': ' + a);
    s = s.replace(a, () => b.replace(/\n/g, nl));
  }
  fs.writeFileSync(f, s);
};

