import { exCreate, exStep } from 'D:/2026 - Tuan/danang-vite/src/explore/flight';
import { CONFIG } from 'D:/2026 - Tuan/danang-vite/src/config';
const C = CONFIG.explore as any, B = C.bounds, dt = 1 / 60;
const onEdge = (s: any) => s.pos.x === B.x0 || s.pos.x === B.x1 || s.pos.z === B.z0 || s.pos.z === B.z1;
const mx = (B.x0 + B.x1) / 2, mz = (B.z0 + B.z1) / 2;
for (const sp of [C.speedMin, 25, C.speed, 75, C.speedMax]) {
  let clamped = 0, cases = 0, maxFlips = 0; const bad: string[] = [];
  for (const off of [150, 300]) {
    const starts = [[B.x1 - off, mz, 0], [B.x0 + off, mz, Math.PI], [mx, B.z0 + off, Math.PI / 2], [mx, B.z1 - off, -Math.PI / 2],
      [B.x1 - off, B.z0 + off, Math.PI / 4], [B.x1 - off, B.z0 + off, Math.PI / 2], [B.x0 + off, B.z1 - off, -3 * Math.PI / 4], [B.x0 + off, B.z1 - off, -Math.PI / 2]];
    starts.forEach(([x, z, yaw], si) => { for (const turn of [0, 1, -1] as const) {
      const s: any = exCreate(); s.pos.set(x, 300, z); s.yaw = yaw; s.bank = 0; s.speed = sp;
      let c = 0, flips = 0, prev = 0, N = 180 * 60;
      for (let i = 0; i < N; i++) { exStep(s, { turn, climb: 0 }, dt); if (onEdge(s)) c++;
        if (i >= N - 3600) { const g = Math.sign(s.bank); if (g && prev && g !== prev) flips++; if (g) prev = g; } }
      clamped += c; cases++; maxFlips = Math.max(maxFlips, flips); if (c) bad.push(`off${off}/s${si}/t${turn}:${c}`);
    } });
  }
  console.log(sp, 'm/s', { cases, clamped, maxFlips }, bad.join(' '));
}

